def g(n):
    return n**2 - n + 1

# Check the first 10 values and their parity
results = {}
for n in range(10):
    value = g(n)
    parity = "Odd" if value % 2 != 0 else "Even"
    results[n] = (value, parity)

print("n | g(n) | Parity")
print("-" * 20)
for n, (val, parity) in results.items():
    print(f"{n} | {val} | {parity}")

def calculate_T_k_parity(k):
    # Parity of triangular number T_k = k(k+1)/2
    # Sequence: 0, 1, 1, 0, 0, 1, 1, 0, ... (period 4)
    return (k % 4) in (0, 3) # True if Even (0), False if Odd (1)

def is_f_odd(x, y):
    k = x + y
    T_k_is_even = calculate_T_k_parity(k)

    if x % 2 == 0:  # x is even. f is odd if T_k is odd (i.e., T_k_is_even is False)
        return not T_k_is_even
    else:  # x is odd. f is odd if T_k is even (i.e., T_k_is_even is True)
        return T_k_is_even

R = 100
N = 0
for x in range(R):
    for y in range(R):
        if is_f_odd(x, y):
            N += 1

print(f"N for standard diagonal enumeration: {N}")
